with open("evaluations.json") as f:
    evals = json.load(f)

y = {e["iteration"]: e["target_dissimilarity"] for e in evals}

# Check all pairwise differences among all 13 iterations multiplied by various powers of 10 or divided by dx!
for i in range(1, 14):
    for j in range(i+1, 14):
        diff = y[i] - y[j]
        # check if diff * 1e12 is close to an integer or 0.1 of an integer
        val = diff * 1e13
        if abs(val - round(val)) < 1e-2:
            print(f"y[{i:2d}] - y[{j:2d}] = {diff:+.16f} (exact at 1e-13!)")
"}

