with open("evaluations.json") as f:
    evals = json.load(f)

y = {e["iteration"]: e["target_dissimilarity"] for e in evals}
dy = {k: v - y[5] for k, v in y.items()}

s = dy[14] + dy[13] + dy[7]
print(f"dy[14] + dy[13] + dy[7] = {s:.16f}")
print(f"(dy[14] + dy[13] + dy[7]) * 1e12 mod 1 = {(s * 1e12) % 1:.6f}")

# Let's search for ALL small integer linear combinations of dy[i] that have (sum * 1e12) mod 1 == 0!
rem = {k: (v * 1e12) % 1 for k, v in dy.items()}
for k in rem:
    if rem[k] > 0.5: rem[k] -= 1.0
    print(f"Iter {k:2d}: rem12 = {rem[k]:+.6f}")
"}

